#[derive(Debug, Clone, PartialEq, Default)]
pub struct ContainerItemsItem {
    /// `CNTO`, required.
    pub entry: Option<Sub<ContainerItemsItemEntry>>,
    /// `COED`, optional.
    pub extra_data: Option<Sub<ContainerItemsItemExtraData>>,
}

impl ContainerItemsItem {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"CNTO",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"COED",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.entry,
                    subs,
                    *index,
                    "ContainerItems.Item.CNTO",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.extra_data,
                    subs,
                    *index,
                    "ContainerItems.Item.COED",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"CNTO", self.entry.as_ref());
        emit(out, *b"COED", self.extra_data.as_ref());
    }
}

