#[derive(Debug, Clone, PartialEq, Default)]
pub struct ContainerItems {
    /// `COCT`, required.
    pub count: Option<Sub<u32>>,
    /// Group `Item`, repeated.
    pub item: Vec<ContainerItemsItem>,
}

impl ContainerItems {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"COCT",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ContainerItemsItem::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.count,
                    subs,
                    *index,
                    "ContainerItems.COCT",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 1, hits } => {
                    let mut group = ContainerItemsItem::default();
                    group.fill(hits, subs, ctx, extra);
                    self.item.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"COCT", self.count.as_ref());
        for group in &self.item {
            group.emit(out);
        }
    }
}

