#[derive(Debug, Clone, PartialEq, Default)]
pub struct Effect {
    /// `EFID`, required.
    pub base_effect: Option<Sub<FormId>>,
    /// `EFIT`, required.
    pub data: Option<Sub<EffectData>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `MNAM`, optional.
    pub magnitude_global: Option<Sub<FormId>>,
    /// `ANAM`, optional.
    pub area_global: Option<Sub<FormId>>,
    /// `ZNAM`, optional.
    pub duration_global: Option<Sub<FormId>>,
    /// `EFIF`, optional.
    pub flags: Option<Sub<EffectFlags>>,
    /// `MUID`, optional.
    pub index_uid: Option<Sub<u32>>,
}

impl Effect {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EFID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"EFIT",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"MNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ZNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"EFIF",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"MUID",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.base_effect,
                    subs,
                    *index,
                    "Effect.EFID",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => {
                    put(&mut self.data, subs, *index, "Effect.EFIT", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 3, index } => put(
                    &mut self.magnitude_global,
                    subs,
                    *index,
                    "Effect.MNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.area_global,
                    subs,
                    *index,
                    "Effect.ANAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => put(
                    &mut self.duration_global,
                    subs,
                    *index,
                    "Effect.ZNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 6, index } => {
                    put(&mut self.flags, subs, *index, "Effect.EFIF", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.index_uid, subs, *index, "Effect.MUID", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EFID", self.base_effect.as_ref());
        emit(out, *b"EFIT", self.data.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"MNAM", self.magnitude_global.as_ref());
        emit(out, *b"ANAM", self.area_global.as_ref());
        emit(out, *b"ZNAM", self.duration_global.as_ref());
        emit(out, *b"EFIF", self.flags.as_ref());
        emit(out, *b"MUID", self.index_uid.as_ref());
    }
}

