/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ActiFlags(pub u16);

impl ActiFlags {
    pub const NO_DISPLACEMENT: u16 = 0x1;
    pub const IGNORED_BY_SANDBOX: u16 = 0x2;
    pub const IS_WATER: u16 = 0x4;
    pub const NON_PLANAR: u16 = 0x8;
    pub const IS_A_RADIO: u16 = 0x10;
    pub const ALLOW_DISPLACEMENTS: u16 = 0x20;
    pub const USE_GLOBAL_PROBE: u16 = 0x40;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u16) -> bool {
        self.0 & mask == mask
    }
}

impl Field for ActiFlags {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u16::read(r, field, ctx).map(Self)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.0.write(out);
    }
}

impl Visit for ActiFlags {}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct ActiRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<ObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `OPDS`, optional.
    pub object_palette_defaults: Option<Sub<ObjectPaletteDefaults>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<Transforms>>,
    /// `SNTP`, optional.
    pub snap_template: Option<Sub<FormId>>,
    /// `SNBH`, optional.
    pub snap_behavior: Option<Sub<FormId>>,
    /// `DEFL`, optional.
    pub default_layer: Option<Sub<FormId>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Group `Model`, required.
    pub model: Option<Model>,
    /// Group `Destructible`, optional.
    pub destructible: Option<Destructible>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `PRPS`, optional.
    pub properties: Option<Sub<ActiProperties>>,
    /// `FTYP`, optional.
    pub forced_loc_ref_types: Option<Sub<ActiForcedLocRefTypes>>,
    /// `NTRM`, optional.
    pub native_terminal: Option<Sub<FormId>>,
    /// `PNAM`, required.
    pub marker_color: Option<Sub<ColorRgb>>,
    /// `ALSH`, optional.
    pub looping_sound: Option<Sub<SoundReference>>,
    /// `ACSH`, optional.
    pub activate_sound: Option<Sub<SoundReference>>,
    /// `WMAT`, optional.
    pub water_material: Option<Sub<ZString>>,
    /// `WTFM`, optional.
    pub water: Option<Sub<FormId>>,
    /// `ATTX`, optional.
    pub activate_text_override: Option<Sub<LString>>,
    /// `FNAM`, required.
    pub flags: Option<Sub<ActiFlags>>,
    /// `JNAM`, required.
    pub activation_angle_player: Option<Sub<u16>>,
    /// `INAM`, optional.
    pub activation_angle_invert_facing: Option<Sub<Empty>>,
    /// `RADR`, optional.
    pub radio_receiver: Option<Sub<RadioReceiver>>,
    /// `CITC`, optional.
    pub condition_count: Option<Sub<u32>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `NVNM`, optional.
    pub navmesh_geometry: Option<Sub<Bytes>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl ActiRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OPDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNTP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNBH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DEFL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: Model::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Destructible::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"PRPS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FTYP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NTRM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ALSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ACSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"WMAT",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"WTFM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ATTX",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"JNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"INAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"RADR",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CITC",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"NVNM",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "ACTI.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "ACTI.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "ACTI.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "ACTI.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.object_palette_defaults,
                    subs,
                    *index,
                    "ACTI.OPDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.transforms, subs, *index, "ACTI.PTT2", ctx, extra)
                }
                Hit::Sub { member: 6, index } => put(
                    &mut self.snap_template,
                    subs,
                    *index,
                    "ACTI.SNTP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 7, index } => put(
                    &mut self.snap_behavior,
                    subs,
                    *index,
                    "ACTI.SNBH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => put(
                    &mut self.default_layer,
                    subs,
                    *index,
                    "ACTI.DEFL",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 9, index } => {
                    put(&mut self.xalg_flags, subs, *index, "ACTI.XALG", ctx, extra)
                }
                Hit::Group { member: 10, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 11, index } => {
                    put(&mut self.name, subs, *index, "ACTI.FULL", ctx, extra)
                }
                Hit::Group { member: 12, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                Hit::Group { member: 13, hits } if self.destructible.is_none() => {
                    let mut group = Destructible::default();
                    group.fill(hits, subs, ctx, extra);
                    self.destructible = Some(group);
                }
                Hit::Group { member: 14, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 15, index } => {
                    put(&mut self.properties, subs, *index, "ACTI.PRPS", ctx, extra)
                }
                Hit::Sub { member: 16, index } => put(
                    &mut self.forced_loc_ref_types,
                    subs,
                    *index,
                    "ACTI.FTYP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => put(
                    &mut self.native_terminal,
                    subs,
                    *index,
                    "ACTI.NTRM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => put(
                    &mut self.marker_color,
                    subs,
                    *index,
                    "ACTI.PNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 19, index } => put(
                    &mut self.looping_sound,
                    subs,
                    *index,
                    "ACTI.ALSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 20, index } => put(
                    &mut self.activate_sound,
                    subs,
                    *index,
                    "ACTI.ACSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => put(
                    &mut self.water_material,
                    subs,
                    *index,
                    "ACTI.WMAT",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 22, index } => {
                    put(&mut self.water, subs, *index, "ACTI.WTFM", ctx, extra)
                }
                Hit::Sub { member: 23, index } => put(
                    &mut self.activate_text_override,
                    subs,
                    *index,
                    "ACTI.ATTX",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 24, index } => {
                    put(&mut self.flags, subs, *index, "ACTI.FNAM", ctx, extra)
                }
                Hit::Sub { member: 25, index } => put(
                    &mut self.activation_angle_player,
                    subs,
                    *index,
                    "ACTI.JNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 26, index } => put(
                    &mut self.activation_angle_invert_facing,
                    subs,
                    *index,
                    "ACTI.INAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 27, index } => put(
                    &mut self.radio_receiver,
                    subs,
                    *index,
                    "ACTI.RADR",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 28, index } => put(
                    &mut self.condition_count,
                    subs,
                    *index,
                    "ACTI.CITC",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 29, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 30, index } => put(
                    &mut self.navmesh_geometry,
                    subs,
                    *index,
                    "ACTI.NVNM",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"OPDS", self.object_palette_defaults.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        emit(out, *b"SNTP", self.snap_template.as_ref());
        emit(out, *b"SNBH", self.snap_behavior.as_ref());
        emit(out, *b"DEFL", self.default_layer.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        if let Some(group) = &self.model {
            group.emit(out);
        }
        if let Some(group) = &self.destructible {
            group.emit(out);
        }
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"PRPS", self.properties.as_ref());
        emit(out, *b"FTYP", self.forced_loc_ref_types.as_ref());
        emit(out, *b"NTRM", self.native_terminal.as_ref());
        emit(out, *b"PNAM", self.marker_color.as_ref());
        emit(out, *b"ALSH", self.looping_sound.as_ref());
        emit(out, *b"ACSH", self.activate_sound.as_ref());
        emit(out, *b"WMAT", self.water_material.as_ref());
        emit(out, *b"WTFM", self.water.as_ref());
        emit(out, *b"ATTX", self.activate_text_override.as_ref());
        emit(out, *b"FNAM", self.flags.as_ref());
        emit(out, *b"JNAM", self.activation_angle_player.as_ref());
        emit(out, *b"INAM", self.activation_angle_invert_facing.as_ref());
        emit(out, *b"RADR", self.radio_receiver.as_ref());
        emit(out, *b"CITC", self.condition_count.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"NVNM", self.navmesh_geometry.as_ref());
    }
}

