impl ActiRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"ACTI";
    /// Record-header flag.
    pub const FLAG_HEADING_MARKER: u32 = 0x4;
    /// Record-header flag.
    pub const FLAG_NON_OCCLUDER: u32 = 0x10;
    /// Record-header flag.
    pub const FLAG_NEVER_FADES: u32 = 0x40;
    /// Record-header flag.
    pub const FLAG_MUST_UPDATE_ANIMS: u32 = 0x100;
    /// Record-header flag.
    pub const FLAG_HIDDEN_FROM_LOCAL_MAP: u32 = 0x200;
    /// Record-header flag.
    pub const FLAG_HEADTRACK_MARKER: u32 = 0x400;
    /// Record-header flag.
    pub const FLAG_USED_AS_PLATFORM: u32 = 0x800;
    /// Record-header flag.
    pub const FLAG_PACK_IN_USE_ONLY: u32 = 0x2000;
    /// Record-header flag.
    pub const FLAG_HAS_DISTANT_LOD: u32 = 0x8000;
    /// Record-header flag.
    pub const FLAG_RANDOM_ANIM_START: u32 = 0x10000;
    /// Record-header flag.
    pub const FLAG_DANGEROUS: u32 = 0x20000;
    /// Record-header flag.
    pub const FLAG_HAS_CURRENTS: u32 = 0x80000;
    /// Record-header flag.
    pub const FLAG_IGNORE_OBJECT_INTERACTION: u32 = 0x100000;
    /// Record-header flag.
    pub const FLAG_IS_MARKER: u32 = 0x800000;
    /// Record-header flag.
    pub const FLAG_OBSTACLE: u32 = 0x2000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_FILTER: u32 = 0x4000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_BOUNDING_BOX: u32 = 0x8000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_ONLY_CUT: u32 = 0x10000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_IGNORE_EROSION: u32 = 0x20000000;
    /// Record-header flag.
    pub const FLAG_NAVMESH_GROUND: u32 = 0x40000000;
    /// Record-header flag.
    pub const FLAG_MUST_BE_UNIQUE: u32 = 0x80000000;

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at the
    /// indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("ACTI", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("ACTI", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("ACTI", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("ACTI", &mut out);
        out
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct AddnRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `OBND`, required.
    pub obnd: Option<Sub<Bytes>>,
    /// `ODTY`, required.
    pub odty: Option<Sub<Bytes>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `MODL`, optional.
    pub modl: Option<Sub<Bytes>>,
    /// `FLLD`, required.
    pub flld: Option<Sub<Bytes>>,
    /// `DATA`, required.
    pub data: Option<Sub<Bytes>>,
    /// `LNAM`, optional.
    pub lnam: Option<Sub<Bytes>>,
    /// `PSDF`, required.
    pub psdf: Option<Sub<Bytes>>,
    /// `DNAM`, required.
    pub dnam: Option<Sub<Bytes>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl AddnRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"MODL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FLLD",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"LNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PSDF",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "ADDN.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.obnd, subs, *index, "ADDN.OBND", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.odty, subs, *index, "ADDN.ODTY", ctx, extra)
                }
                Hit::Group { member: 3, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.modl, subs, *index, "ADDN.MODL", ctx, extra)
                }
                Hit::Sub { member: 5, index } => {
                    put(&mut self.flld, subs, *index, "ADDN.FLLD", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.data, subs, *index, "ADDN.DATA", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.lnam, subs, *index, "ADDN.LNAM", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.psdf, subs, *index, "ADDN.PSDF", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.dnam, subs, *index, "ADDN.DNAM", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"OBND", self.obnd.as_ref());
        emit(out, *b"ODTY", self.odty.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"MODL", self.modl.as_ref());
        emit(out, *b"FLLD", self.flld.as_ref());
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"LNAM", self.lnam.as_ref());
        emit(out, *b"PSDF", self.psdf.as_ref());
        emit(out, *b"DNAM", self.dnam.as_ref());
    }
}

impl Visit for AddnRecord {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.bfcb_block, "ADDN.BfcbBlock", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.bfcb_block, "ADDN.BfcbBlock", out);
    }
}

