#[derive(Debug, Clone, PartialEq, Default)]
pub struct ArmoRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<ObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<Transforms>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `EITM`, optional.
    pub enchantment: Option<Sub<FormId>>,
    /// Group `MaleWorldModel`, required.
    pub male_world_model: Option<ArmoMaleWorldModel>,
    /// Group `FemaleWorldModel`, required.
    pub female_world_model: Option<ArmoFemaleWorldModel>,
    /// `BO64`, required.
    pub biped_slots: Option<Sub<BipedSlots>>,
    /// Group `Destructible`, optional.
    pub destructible: Option<Destructible>,
    /// `PUSH`, optional.
    pub pickup_sound: Option<Sub<SoundReference>>,
    /// `PDSH`, optional.
    pub putdown_sound: Option<Sub<SoundReference>>,
    /// `ETYP`, optional.
    pub equipment_type: Option<Sub<FormId>>,
    /// `BIDS`, optional.
    pub block_bash_impact_data_set: Option<Sub<FormId>>,
    /// `BAMT`, optional.
    pub alternate_block_material: Option<Sub<FormId>>,
    /// `RNAM`, required.
    pub race: Option<Sub<FormId>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `DESC`, required.
    pub description: Option<Sub<LString>>,
    /// `INRD`, optional.
    pub instance_naming: Option<Sub<FormId>>,
    /// Group `Addon`, repeated.
    pub addon: Vec<ArmoAddon>,
    /// `DATA`, required.
    pub data: Option<Sub<ArmoData>>,
    /// `FNAM`, required.
    pub ratings: Option<Sub<ArmoRatings>>,
    /// `DAMA`, optional.
    pub resistances: Option<Sub<ArmoResistances>>,
    /// `APPR`, optional.
    pub attach_parent_slots: Option<Sub<ArmoAttachParentSlots>>,
    /// Group `ObteBlock`, optional.
    pub obte_block: Option<ObteBlock>,
    /// `AVSG`, optional.
    pub voice_switch: Option<Sub<ArmoVoiceSwitch>>,
    /// `AFSG`, optional.
    pub foley_switch: Option<Sub<ArmoFoleySwitch>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl ArmoRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"EITM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: ArmoMaleWorldModel::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: ArmoFemaleWorldModel::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"BO64",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Destructible::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"PUSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PDSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ETYP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BIDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BAMT",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"RNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DESC",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"INRD",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ArmoAddon::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DAMA",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"APPR",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: ObteBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"AVSG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"AFSG",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "ARMO.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "ARMO.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "ARMO.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "ARMO.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => {
                    put(&mut self.transforms, subs, *index, "ARMO.PTT2", ctx, extra)
                }
                Hit::Group { member: 5, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.name, subs, *index, "ARMO.FULL", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.enchantment, subs, *index, "ARMO.EITM", ctx, extra)
                }
                Hit::Group { member: 8, hits } if self.male_world_model.is_none() => {
                    let mut group = ArmoMaleWorldModel::default();
                    group.fill(hits, subs, ctx, extra);
                    self.male_world_model = Some(group);
                }
                Hit::Group { member: 9, hits } if self.female_world_model.is_none() => {
                    let mut group = ArmoFemaleWorldModel::default();
                    group.fill(hits, subs, ctx, extra);
                    self.female_world_model = Some(group);
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.biped_slots, subs, *index, "ARMO.BO64", ctx, extra)
                }
                Hit::Group { member: 11, hits } if self.destructible.is_none() => {
                    let mut group = Destructible::default();
                    group.fill(hits, subs, ctx, extra);
                    self.destructible = Some(group);
                }
                Hit::Sub { member: 12, index } => put(
                    &mut self.pickup_sound,
                    subs,
                    *index,
                    "ARMO.PUSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 13, index } => put(
                    &mut self.putdown_sound,
                    subs,
                    *index,
                    "ARMO.PDSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 14, index } => put(
                    &mut self.equipment_type,
                    subs,
                    *index,
                    "ARMO.ETYP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 15, index } => put(
                    &mut self.block_bash_impact_data_set,
                    subs,
                    *index,
                    "ARMO.BIDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => put(
                    &mut self.alternate_block_material,
                    subs,
                    *index,
                    "ARMO.BAMT",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => {
                    put(&mut self.race, subs, *index, "ARMO.RNAM", ctx, extra)
                }
                Hit::Group { member: 18, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 19, index } => {
                    put(&mut self.description, subs, *index, "ARMO.DESC", ctx, extra)
                }
                Hit::Sub { member: 20, index } => put(
                    &mut self.instance_naming,
                    subs,
                    *index,
                    "ARMO.INRD",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 21, hits } => {
                    let mut group = ArmoAddon::default();
                    group.fill(hits, subs, ctx, extra);
                    self.addon.push(group);
                }
                Hit::Sub { member: 22, index } => {
                    put(&mut self.data, subs, *index, "ARMO.DATA", ctx, extra)
                }
                Hit::Sub { member: 23, index } => {
                    put(&mut self.ratings, subs, *index, "ARMO.FNAM", ctx, extra)
                }
                Hit::Sub { member: 24, index } => {
                    put(&mut self.resistances, subs, *index, "ARMO.DAMA", ctx, extra)
                }
                Hit::Sub { member: 25, index } => put(
                    &mut self.attach_parent_slots,
                    subs,
                    *index,
                    "ARMO.APPR",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 26, hits } if self.obte_block.is_none() => {
                    let mut group = ObteBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.obte_block = Some(group);
                }
                Hit::Sub { member: 27, index } => put(
                    &mut self.voice_switch,
                    subs,
                    *index,
                    "ARMO.AVSG",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 28, index } => put(
                    &mut self.foley_switch,
                    subs,
                    *index,
                    "ARMO.AFSG",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"EITM", self.enchantment.as_ref());
        if let Some(group) = &self.male_world_model {
            group.emit(out);
        }
        if let Some(group) = &self.female_world_model {
            group.emit(out);
        }
        emit(out, *b"BO64", self.biped_slots.as_ref());
        if let Some(group) = &self.destructible {
            group.emit(out);
        }
        emit(out, *b"PUSH", self.pickup_sound.as_ref());
        emit(out, *b"PDSH", self.putdown_sound.as_ref());
        emit(out, *b"ETYP", self.equipment_type.as_ref());
        emit(out, *b"BIDS", self.block_bash_impact_data_set.as_ref());
        emit(out, *b"BAMT", self.alternate_block_material.as_ref());
        emit(out, *b"RNAM", self.race.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"DESC", self.description.as_ref());
        emit(out, *b"INRD", self.instance_naming.as_ref());
        for group in &self.addon {
            group.emit(out);
        }
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"FNAM", self.ratings.as_ref());
        emit(out, *b"DAMA", self.resistances.as_ref());
        emit(out, *b"APPR", self.attach_parent_slots.as_ref());
        if let Some(group) = &self.obte_block {
            group.emit(out);
        }
        emit(out, *b"AVSG", self.voice_switch.as_ref());
        emit(out, *b"AFSG", self.foley_switch.as_ref());
    }
}

