#[derive(Debug, Clone, PartialEq, Default)]
pub struct BiomRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `SNAM`, optional.
    pub filter_string: Option<Sub<ZString>>,
    /// `PNAM`, optional.
    pub flora: Option<Sub<BiomFlora>>,
    /// `RNAM`, repeated.
    pub resource_generation: Vec<Sub<FormId>>,
    /// Group `Mask`, repeated.
    pub mask: Vec<BiomMask>,
    /// `ONAM`, repeated.
    pub object_swaps: Vec<Sub<FormId>>,
    /// `NAM1`, repeated.
    pub material_swaps: Vec<Sub<FormId>>,
    /// `ENAM`, optional.
    pub climate: Option<Sub<FormId>>,
    /// Group `Water`, required.
    pub water: Option<BiomWater>,
    /// `WNAM`, required.
    pub block_density_mult: Option<Sub<f32>>,
    /// `YNAM`, required.
    pub cell_density_mult: Option<Sub<f32>>,
    /// `UNAM`, required.
    pub scan_worldspace_mult: Option<Sub<f32>>,
    /// `ZNAM`, optional.
    pub child: Option<Sub<FormId>>,
    /// `BIAS`, optional.
    pub ambience_set: Option<Sub<FormId>>,
    /// `BIMT`, optional.
    pub music_type: Option<Sub<FormId>>,
    /// `NAM0`, optional.
    pub time_of_day_data: Option<Sub<FormId>>,
    /// `NNAM`, optional.
    pub pattern_style: Option<Sub<FormId>>,
    /// `CNAM`, required.
    pub color: Option<Sub<ColorBgra>>,
    /// `BMC1`, required.
    pub surface_color1: Option<Sub<ColorBgra>>,
    /// `BMC2`, required.
    pub surface_color2: Option<Sub<ColorBgra>>,
    /// `BMC3`, required.
    pub rock_tint: Option<Sub<ColorBgra>>,
    /// `TNAM`, required.
    pub biome_type: Option<Sub<BiomBiomeType>>,
    /// Group `Marker`, repeated.
    pub marker: Vec<BiomMarker>,
    /// Group `Terrain`, repeated.
    pub terrain: Vec<BiomTerrain>,
    /// `TX16`, optional.
    pub ground_layer_normal: Option<Sub<ZString>>,
    /// `BTPS`, required.
    pub terrain_noise: Option<Sub<BiomTerrainNoise>>,
    /// `BDFS`, required.
    pub distant_view: Option<Sub<BiomDistantView>>,
    /// `EFSD`, optional.
    pub global_layer_material: Option<Sub<ZString>>,
    /// `NAM2`, required.
    pub block_density_mult_global: Option<Sub<FormId>>,
    /// `NAM3`, required.
    pub cell_density_mult_global: Option<Sub<FormId>>,
    /// `NAM4`, required.
    pub scan_worldspace_mult_global: Option<Sub<FormId>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl BiomRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"RNAM",
            card: Card::Repeated,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BiomMask::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"NAM1",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"ENAM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: BiomWater::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"WNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"YNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"UNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ZNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BIAS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BIMT",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NAM0",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"CNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BMC1",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BMC2",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BMC3",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"TNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BiomMarker::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BiomTerrain::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"TX16",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BTPS",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BDFS",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"EFSD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NAM2",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"NAM3",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"NAM4",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "BIOM.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.name, subs, *index, "BIOM.FULL", ctx, extra)
                }
                Hit::Group { member: 2, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 3, index } => put(
                    &mut self.filter_string,
                    subs,
                    *index,
                    "BIOM.SNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => {
                    put(&mut self.flora, subs, *index, "BIOM.PNAM", ctx, extra)
                }
                Hit::Sub { member: 5, index } => push(
                    &mut self.resource_generation,
                    subs,
                    *index,
                    "BIOM.RNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 6, hits } => {
                    let mut group = BiomMask::default();
                    group.fill(hits, subs, ctx, extra);
                    self.mask.push(group);
                }
                Hit::Sub { member: 7, index } => push(
                    &mut self.object_swaps,
                    subs,
                    *index,
                    "BIOM.ONAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => push(
                    &mut self.material_swaps,
                    subs,
                    *index,
                    "BIOM.NAM1",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 9, index } => {
                    put(&mut self.climate, subs, *index, "BIOM.ENAM", ctx, extra)
                }
                Hit::Group { member: 10, hits } if self.water.is_none() => {
                    let mut group = BiomWater::default();
                    group.fill(hits, subs, ctx, extra);
                    self.water = Some(group);
                }
                Hit::Sub { member: 11, index } => put(
                    &mut self.block_density_mult,
                    subs,
                    *index,
                    "BIOM.WNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 12, index } => put(
                    &mut self.cell_density_mult,
                    subs,
                    *index,
                    "BIOM.YNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 13, index } => put(
                    &mut self.scan_worldspace_mult,
                    subs,
                    *index,
                    "BIOM.UNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 14, index } => {
                    put(&mut self.child, subs, *index, "BIOM.ZNAM", ctx, extra)
                }
                Hit::Sub { member: 15, index } => put(
                    &mut self.ambience_set,
                    subs,
                    *index,
                    "BIOM.BIAS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => {
                    put(&mut self.music_type, subs, *index, "BIOM.BIMT", ctx, extra)
                }
                Hit::Sub { member: 17, index } => put(
                    &mut self.time_of_day_data,
                    subs,
                    *index,
                    "BIOM.NAM0",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => put(
                    &mut self.pattern_style,
                    subs,
                    *index,
                    "BIOM.NNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 19, index } => {
                    put(&mut self.color, subs, *index, "BIOM.CNAM", ctx, extra)
                }
                Hit::Sub { member: 20, index } => put(
                    &mut self.surface_color1,
                    subs,
                    *index,
                    "BIOM.BMC1",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => put(
                    &mut self.surface_color2,
                    subs,
                    *index,
                    "BIOM.BMC2",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 22, index } => {
                    put(&mut self.rock_tint, subs, *index, "BIOM.BMC3", ctx, extra)
                }
                Hit::Sub { member: 23, index } => {
                    put(&mut self.biome_type, subs, *index, "BIOM.TNAM", ctx, extra)
                }
                Hit::Group { member: 24, hits } => {
                    let mut group = BiomMarker::default();
                    group.fill(hits, subs, ctx, extra);
                    self.marker.push(group);
                }
                Hit::Group { member: 25, hits } => {
                    let mut group = BiomTerrain::default();
                    group.fill(hits, subs, ctx, extra);
                    self.terrain.push(group);
                }
                Hit::Sub { member: 26, index } => put(
                    &mut self.ground_layer_normal,
                    subs,
                    *index,
                    "BIOM.TX16",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 27, index } => put(
                    &mut self.terrain_noise,
                    subs,
                    *index,
                    "BIOM.BTPS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 28, index } => put(
                    &mut self.distant_view,
                    subs,
                    *index,
                    "BIOM.BDFS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 29, index } => put(
                    &mut self.global_layer_material,
                    subs,
                    *index,
                    "BIOM.EFSD",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 30, index } => put(
                    &mut self.block_density_mult_global,
                    subs,
                    *index,
                    "BIOM.NAM2",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 31, index } => put(
                    &mut self.cell_density_mult_global,
                    subs,
                    *index,
                    "BIOM.NAM3",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 32, index } => put(
                    &mut self.scan_worldspace_mult_global,
                    subs,
                    *index,
                    "BIOM.NAM4",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"SNAM", self.filter_string.as_ref());
        emit(out, *b"PNAM", self.flora.as_ref());
        for value in &self.resource_generation {
            emit(out, *b"RNAM", Some(value));
        }
        for group in &self.mask {
            group.emit(out);
        }
        for value in &self.object_swaps {
            emit(out, *b"ONAM", Some(value));
        }
        for value in &self.material_swaps {
            emit(out, *b"NAM1", Some(value));
        }
        emit(out, *b"ENAM", self.climate.as_ref());
        if let Some(group) = &self.water {
            group.emit(out);
        }
        emit(out, *b"WNAM", self.block_density_mult.as_ref());
        emit(out, *b"YNAM", self.cell_density_mult.as_ref());
        emit(out, *b"UNAM", self.scan_worldspace_mult.as_ref());
        emit(out, *b"ZNAM", self.child.as_ref());
        emit(out, *b"BIAS", self.ambience_set.as_ref());
        emit(out, *b"BIMT", self.music_type.as_ref());
        emit(out, *b"NAM0", self.time_of_day_data.as_ref());
        emit(out, *b"NNAM", self.pattern_style.as_ref());
        emit(out, *b"CNAM", self.color.as_ref());
        emit(out, *b"BMC1", self.surface_color1.as_ref());
        emit(out, *b"BMC2", self.surface_color2.as_ref());
        emit(out, *b"BMC3", self.rock_tint.as_ref());
        emit(out, *b"TNAM", self.biome_type.as_ref());
        for group in &self.marker {
            group.emit(out);
        }
        for group in &self.terrain {
            group.emit(out);
        }
        emit(out, *b"TX16", self.ground_layer_normal.as_ref());
        emit(out, *b"BTPS", self.terrain_noise.as_ref());
        emit(out, *b"BDFS", self.distant_view.as_ref());
        emit(out, *b"EFSD", self.global_layer_material.as_ref());
        emit(out, *b"NAM2", self.block_density_mult_global.as_ref());
        emit(out, *b"NAM3", self.cell_density_mult_global.as_ref());
        emit(out, *b"NAM4", self.scan_worldspace_mult_global.as_ref());
    }
}

