#[derive(Debug, Clone, PartialEq, Default)]
pub struct ContRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<ObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `OPDS`, optional.
    pub object_palette_defaults: Option<Sub<ObjectPaletteDefaults>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<Transforms>>,
    /// `SNTP`, optional.
    pub snap_template: Option<Sub<FormId>>,
    /// `SNBH`, optional.
    pub snap_behavior: Option<Sub<FormId>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Group `Model`, required.
    pub model: Option<Model>,
    /// Group `ContainerItems`, optional.
    pub container_items: Option<ContainerItems>,
    /// Group `Destructible`, optional.
    pub destructible: Option<Destructible>,
    /// `DATA`, required.
    pub flags: Option<Sub<ContFlags>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `FTYP`, optional.
    pub forced_loc_ref_types: Option<Sub<ContForcedLocRefTypes>>,
    /// `NTRM`, optional.
    pub native_terminal: Option<Sub<FormId>>,
    /// `PRPS`, optional.
    pub properties: Option<Sub<ContProperties>>,
    /// `APPR`, optional.
    pub attach_parent_slots: Option<Sub<ContAttachParentSlots>>,
    /// Group `ObteBlock`, optional.
    pub obte_block: Option<ObteBlock>,
    /// `WED0`, optional.
    pub open_sound: Option<Sub<SoundReference>>,
    /// `WED1`, optional.
    pub close_sound: Option<Sub<SoundReference>>,
    /// `ONAM`, optional.
    pub contains_only_filter: Option<Sub<FormId>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl ContRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OPDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNTP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNBH",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: Model::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: ContainerItems::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Destructible::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FTYP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NTRM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PRPS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"APPR",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: ObteBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"WED0",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"WED1",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "CONT.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "CONT.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "CONT.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "CONT.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.object_palette_defaults,
                    subs,
                    *index,
                    "CONT.OPDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.xalg_flags, subs, *index, "CONT.XALG", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.transforms, subs, *index, "CONT.PTT2", ctx, extra)
                }
                Hit::Sub { member: 7, index } => put(
                    &mut self.snap_template,
                    subs,
                    *index,
                    "CONT.SNTP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => put(
                    &mut self.snap_behavior,
                    subs,
                    *index,
                    "CONT.SNBH",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 9, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.name, subs, *index, "CONT.FULL", ctx, extra)
                }
                Hit::Group { member: 11, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                Hit::Group { member: 12, hits } if self.container_items.is_none() => {
                    let mut group = ContainerItems::default();
                    group.fill(hits, subs, ctx, extra);
                    self.container_items = Some(group);
                }
                Hit::Group { member: 13, hits } if self.destructible.is_none() => {
                    let mut group = Destructible::default();
                    group.fill(hits, subs, ctx, extra);
                    self.destructible = Some(group);
                }
                Hit::Sub { member: 14, index } => {
                    put(&mut self.flags, subs, *index, "CONT.DATA", ctx, extra)
                }
                Hit::Group { member: 15, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 16, index } => put(
                    &mut self.forced_loc_ref_types,
                    subs,
                    *index,
                    "CONT.FTYP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => put(
                    &mut self.native_terminal,
                    subs,
                    *index,
                    "CONT.NTRM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => {
                    put(&mut self.properties, subs, *index, "CONT.PRPS", ctx, extra)
                }
                Hit::Sub { member: 19, index } => put(
                    &mut self.attach_parent_slots,
                    subs,
                    *index,
                    "CONT.APPR",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 20, hits } if self.obte_block.is_none() => {
                    let mut group = ObteBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.obte_block = Some(group);
                }
                Hit::Sub { member: 21, index } => {
                    put(&mut self.open_sound, subs, *index, "CONT.WED0", ctx, extra)
                }
                Hit::Sub { member: 22, index } => {
                    put(&mut self.close_sound, subs, *index, "CONT.WED1", ctx, extra)
                }
                Hit::Sub { member: 23, index } => put(
                    &mut self.contains_only_filter,
                    subs,
                    *index,
                    "CONT.ONAM",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"OPDS", self.object_palette_defaults.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        emit(out, *b"SNTP", self.snap_template.as_ref());
        emit(out, *b"SNBH", self.snap_behavior.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        if let Some(group) = &self.model {
            group.emit(out);
        }
        if let Some(group) = &self.container_items {
            group.emit(out);
        }
        if let Some(group) = &self.destructible {
            group.emit(out);
        }
        emit(out, *b"DATA", self.flags.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"FTYP", self.forced_loc_ref_types.as_ref());
        emit(out, *b"NTRM", self.native_terminal.as_ref());
        emit(out, *b"PRPS", self.properties.as_ref());
        emit(out, *b"APPR", self.attach_parent_slots.as_ref());
        if let Some(group) = &self.obte_block {
            group.emit(out);
        }
        emit(out, *b"WED0", self.open_sound.as_ref());
        emit(out, *b"WED1", self.close_sound.as_ref());
        emit(out, *b"ONAM", self.contains_only_filter.as_ref());
    }
}

