#[derive(Debug, Clone, PartialEq)]
pub struct CpthLinks {
    pub parent: FormId,
    pub previous: FormId,
}

impl Field for CpthLinks {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = Field::read(r, "CPTH.ANAM.Parent", ctx)?;
        let f1 = Field::read(r, "CPTH.ANAM.Previous", ctx)?;
        Ok(Self {
            parent: f0,
            previous: f1,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.parent.write(out);
        self.previous.write(out);
    }
}

impl Visit for CpthLinks {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.parent, "CPTH.ANAM.Parent", out);
        visit_form_ids(&self.previous, "CPTH.ANAM.Previous", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.parent, "CPTH.ANAM.Parent", out);
        visit_form_ids_mut(&mut self.previous, "CPTH.ANAM.Previous", out);
    }
}

/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct CpthFlags(pub u8);

impl CpthFlags {
    pub const DISABLE: u8 = 0x1;
    pub const SHOT_LIST: u8 = 0x2;
    pub const DYNAMIC_CAMERA_TIMES: u8 = 0x4;
    pub const RANDOMIZE_PATHS: u8 = 0x40;
    pub const NOT_MUST_HAVE_CAMERA_SHOTS: u8 = 0x80;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u8) -> bool {
        self.0 & mask == mask
    }
}

impl Field for CpthFlags {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.0.write(out);
    }
}

impl Visit for CpthFlags {}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct CpthRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `ANAM`, required.
    pub links: Option<Sub<CpthLinks>>,
    /// `DATA`, required.
    pub flags: Option<Sub<CpthFlags>>,
    /// `SNAM`, repeated.
    pub camera_shots: Vec<Sub<FormId>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl CpthRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Repeated,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "CPTH.EDID", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.links, subs, *index, "CPTH.ANAM", ctx, extra)
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.flags, subs, *index, "CPTH.DATA", ctx, extra)
                }
                Hit::Sub { member: 4, index } => push(
                    &mut self.camera_shots,
                    subs,
                    *index,
                    "CPTH.SNAM",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"ANAM", self.links.as_ref());
        emit(out, *b"DATA", self.flags.as_ref());
        for value in &self.camera_shots {
            emit(out, *b"SNAM", Some(value));
        }
    }
}

impl Visit for CpthRecord {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.conditions, "CPTH.Conditions", out);
        visit_form_ids(&self.links, "CPTH.ANAM", out);
        visit_form_ids(&self.camera_shots, "CPTH.SNAM", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.conditions, "CPTH.Conditions", out);
        visit_form_ids_mut(&mut self.links, "CPTH.ANAM", out);
        visit_form_ids_mut(&mut self.camera_shots, "CPTH.SNAM", out);
    }
}

