#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DialDataCategory {
    Player,
    Command,
    Scene,
    Combat,
    Favor,
    Detection,
    Service,
    Miscellaneous,
    /// A value the definition does not name.
    Other(u8),
}

impl DialDataCategory {
    /// The variant for a stored value.
    pub fn from_raw(raw: u8) -> Self {
        match raw {
            0 => Self::Player,
            1 => Self::Command,
            2 => Self::Scene,
            3 => Self::Combat,
            4 => Self::Favor,
            5 => Self::Detection,
            6 => Self::Service,
            7 => Self::Miscellaneous,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u8 {
        match self {
            Self::Player => 0,
            Self::Command => 1,
            Self::Scene => 2,
            Self::Combat => 3,
            Self::Favor => 4,
            Self::Detection => 5,
            Self::Service => 6,
            Self::Miscellaneous => 7,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for DialDataCategory {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

impl Visit for DialDataCategory {}

