#[derive(Debug, Clone, PartialEq, Default)]
pub struct DialRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `PNAM`, required.
    pub priority: Option<Sub<f32>>,
    /// `BNAM`, optional.
    pub branch: Option<Sub<FormId>>,
    /// `QNAM`, required.
    pub quest: Option<Sub<FormId>>,
    /// `KNAM`, optional.
    pub keyword: Option<Sub<FormId>>,
    /// `ANAM`, optional.
    pub affinity_event: Option<Sub<FormId>>,
    /// `DATA`, required.
    pub data: Option<Sub<DialData>>,
    /// `SNAM`, required.
    pub subtype_name: Option<Sub<Sig>>,
    /// `TIFL`, required.
    pub infos: Option<Sub<DialInfos>>,
    /// `TIFC`, required.
    pub info_count: Option<Sub<u32>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl DialRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"QNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"KNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"TIFL",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"TIFC",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "DIAL.EDID", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.name, subs, *index, "DIAL.FULL", ctx, extra)
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.priority, subs, *index, "DIAL.PNAM", ctx, extra)
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.branch, subs, *index, "DIAL.BNAM", ctx, extra)
                }
                Hit::Sub { member: 5, index } => {
                    put(&mut self.quest, subs, *index, "DIAL.QNAM", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.keyword, subs, *index, "DIAL.KNAM", ctx, extra)
                }
                Hit::Sub { member: 7, index } => put(
                    &mut self.affinity_event,
                    subs,
                    *index,
                    "DIAL.ANAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => {
                    put(&mut self.data, subs, *index, "DIAL.DATA", ctx, extra)
                }
                Hit::Sub { member: 9, index } => put(
                    &mut self.subtype_name,
                    subs,
                    *index,
                    "DIAL.SNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 10, index } => {
                    put(&mut self.infos, subs, *index, "DIAL.TIFL", ctx, extra)
                }
                Hit::Sub { member: 11, index } => {
                    put(&mut self.info_count, subs, *index, "DIAL.TIFC", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"PNAM", self.priority.as_ref());
        emit(out, *b"BNAM", self.branch.as_ref());
        emit(out, *b"QNAM", self.quest.as_ref());
        emit(out, *b"KNAM", self.keyword.as_ref());
        emit(out, *b"ANAM", self.affinity_event.as_ref());
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"SNAM", self.subtype_name.as_ref());
        emit(out, *b"TIFL", self.infos.as_ref());
        emit(out, *b"TIFC", self.info_count.as_ref());
    }
}

impl Visit for DialRecord {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.bfcb_block, "DIAL.BfcbBlock", out);
        visit_form_ids(&self.branch, "DIAL.BNAM", out);
        visit_form_ids(&self.quest, "DIAL.QNAM", out);
        visit_form_ids(&self.keyword, "DIAL.KNAM", out);
        visit_form_ids(&self.affinity_event, "DIAL.ANAM", out);
        visit_form_ids(&self.infos, "DIAL.TIFL", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.bfcb_block, "DIAL.BfcbBlock", out);
        visit_form_ids_mut(&mut self.branch, "DIAL.BNAM", out);
        visit_form_ids_mut(&mut self.quest, "DIAL.QNAM", out);
        visit_form_ids_mut(&mut self.keyword, "DIAL.KNAM", out);
        visit_form_ids_mut(&mut self.affinity_event, "DIAL.ANAM", out);
        visit_form_ids_mut(&mut self.infos, "DIAL.TIFL", out);
    }

    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.name, "DIAL.FULL", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.name, "DIAL.FULL", out);
    }
}

impl DialRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"DIAL";
    /// Record-header flag.
    pub const FLAG_PARTIAL_FORM: u32 = 0x4000;

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at the
    /// indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("DIAL", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("DIAL", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("DIAL", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("DIAL", &mut out);
        out
    }
}

