#[derive(Debug, Clone, PartialEq)]
pub struct IdleLinks {
    pub parent: FormId,
    pub previous: FormId,
}

impl Field for IdleLinks {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = Field::read(r, "IDLE.ANAM.Parent", ctx)?;
        let f1 = Field::read(r, "IDLE.ANAM.Previous", ctx)?;
        Ok(Self {
            parent: f0,
            previous: f1,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.parent.write(out);
        self.previous.write(out);
    }
}

impl Visit for IdleLinks {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.parent, "IDLE.ANAM.Parent", out);
        visit_form_ids(&self.previous, "IDLE.ANAM.Previous", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.parent, "IDLE.ANAM.Parent", out);
        visit_form_ids_mut(&mut self.previous, "IDLE.ANAM.Previous", out);
    }
}

/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct IdleFlags(pub u8);

impl IdleFlags {
    pub const LOOSE: u8 = 0x1;
    pub const PREVIEW: u8 = 0x2;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u8) -> bool {
        self.0 & mask == mask
    }
}

impl Field for IdleFlags {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.0.write(out);
    }
}

impl Visit for IdleFlags {}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct IdleRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `DNAM`, optional.
    pub behavior_graph: Option<Sub<ZString>>,
    /// `ENAM`, optional.
    pub animation_event: Option<Sub<ZString>>,
    /// `ANAM`, required.
    pub links: Option<Sub<IdleLinks>>,
    /// `FNAM`, required.
    pub flags: Option<Sub<IdleFlags>>,
    /// `GNAM`, optional.
    pub animation_file: Option<Sub<ZString>>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl IdleRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ENAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"GNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "IDLE.EDID", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.behavior_graph,
                    subs,
                    *index,
                    "IDLE.DNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.animation_event,
                    subs,
                    *index,
                    "IDLE.ENAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => {
                    put(&mut self.links, subs, *index, "IDLE.ANAM", ctx, extra)
                }
                Hit::Sub { member: 5, index } => {
                    put(&mut self.flags, subs, *index, "IDLE.FNAM", ctx, extra)
                }
                Hit::Sub { member: 6, index } => put(
                    &mut self.animation_file,
                    subs,
                    *index,
                    "IDLE.GNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 7, index } => {
                    put(&mut self.name, subs, *index, "IDLE.FULL", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"DNAM", self.behavior_graph.as_ref());
        emit(out, *b"ENAM", self.animation_event.as_ref());
        emit(out, *b"ANAM", self.links.as_ref());
        emit(out, *b"FNAM", self.flags.as_ref());
        emit(out, *b"GNAM", self.animation_file.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
    }
}

