#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InfoSubtitlePriority {
    Low,
    Normal,
    High,
    Force,
    /// A value the definition does not name.
    Other(u32),
}

impl InfoSubtitlePriority {
    /// The variant for a stored value.
    pub fn from_raw(raw: u32) -> Self {
        match raw {
            0 => Self::Low,
            1 => Self::Normal,
            2 => Self::High,
            3 => Self::Force,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u32 {
        match self {
            Self::Low => 0,
            Self::Normal => 1,
            Self::High => 2,
            Self::Force => 3,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for InfoSubtitlePriority {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u32::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

