#[derive(Debug, Clone, PartialEq, Default)]
pub struct InfoRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<ScriptAttachment>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `ENAM`, required.
    pub response_flags: Option<Sub<InfoResponseFlags>>,
    /// `TPIC`, optional.
    pub previous_topic: Option<Sub<FormId>>,
    /// `DNAM`, optional.
    pub shared_info: Option<Sub<FormId>>,
    /// `GNAM`, optional.
    pub info_group: Option<Sub<FormId>>,
    /// Group `Response`, repeated.
    pub response: Vec<InfoResponse>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `RNAM`, optional.
    pub prompt: Option<Sub<LString>>,
    /// `ANAM`, optional.
    pub speaker: Option<Sub<FormId>>,
    /// `TSCE`, optional.
    pub start_scene: Option<Sub<FormId>>,
    /// `INTV`, optional.
    pub intv: Option<Sub<Bytes>>,
    /// `WED0`, optional.
    pub voice_override: Option<Sub<SoundReference>>,
    /// `TIQS`, optional.
    pub set_parent_quest_stage: Option<Sub<InfoSetParentQuestStage>>,
    /// `NAM0`, required.
    pub start_scene_phase: Option<Sub<ZString>>,
    /// `MODQ`, optional.
    pub reset_global: Option<Sub<FormId>>,
    /// `INAM`, required.
    pub subtitle_priority: Option<Sub<InfoSubtitlePriority>>,
    /// `COCT`, optional.
    pub coct: Option<Sub<Empty>>,
    /// `NAM8`, optional.
    pub affinity_event: Option<Sub<FormId>>,
    /// `SCSP`, optional.
    pub speech_challenge: Option<Sub<FormId>>,
    /// `PERK`, optional.
    pub skill_perk: Option<Sub<FormId>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl InfoRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"ENAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"TPIC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"GNAM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: InfoResponse::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"RNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ANAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"TSCE",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"INTV",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"WED0",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"TIQS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NAM0",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"MODQ",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"INAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"COCT",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NAM8",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SCSP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PERK",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "INFO.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "INFO.VMAD", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 3, index } => put(
                    &mut self.response_flags,
                    subs,
                    *index,
                    "INFO.ENAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.previous_topic,
                    subs,
                    *index,
                    "INFO.TPIC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.shared_info, subs, *index, "INFO.DNAM", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.info_group, subs, *index, "INFO.GNAM", ctx, extra)
                }
                Hit::Group { member: 7, hits } => {
                    let mut group = InfoResponse::default();
                    group.fill(hits, subs, ctx, extra);
                    self.response.push(group);
                }
                Hit::Group { member: 8, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.prompt, subs, *index, "INFO.RNAM", ctx, extra)
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.speaker, subs, *index, "INFO.ANAM", ctx, extra)
                }
                Hit::Sub { member: 11, index } => {
                    put(&mut self.start_scene, subs, *index, "INFO.TSCE", ctx, extra)
                }
                Hit::Sub { member: 12, index } => {
                    put(&mut self.intv, subs, *index, "INFO.INTV", ctx, extra)
                }
                Hit::Sub { member: 13, index } => put(
                    &mut self.voice_override,
                    subs,
                    *index,
                    "INFO.WED0",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 14, index } => put(
                    &mut self.set_parent_quest_stage,
                    subs,
                    *index,
                    "INFO.TIQS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 15, index } => put(
                    &mut self.start_scene_phase,
                    subs,
                    *index,
                    "INFO.NAM0",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => put(
                    &mut self.reset_global,
                    subs,
                    *index,
                    "INFO.MODQ",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => put(
                    &mut self.subtitle_priority,
                    subs,
                    *index,
                    "INFO.INAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 18, index } => {
                    put(&mut self.coct, subs, *index, "INFO.COCT", ctx, extra)
                }
                Hit::Sub { member: 19, index } => put(
                    &mut self.affinity_event,
                    subs,
                    *index,
                    "INFO.NAM8",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 20, index } => put(
                    &mut self.speech_challenge,
                    subs,
                    *index,
                    "INFO.SCSP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => {
                    put(&mut self.skill_perk, subs, *index, "INFO.PERK", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"ENAM", self.response_flags.as_ref());
        emit(out, *b"TPIC", self.previous_topic.as_ref());
        emit(out, *b"DNAM", self.shared_info.as_ref());
        emit(out, *b"GNAM", self.info_group.as_ref());
        for group in &self.response {
            group.emit(out);
        }
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"RNAM", self.prompt.as_ref());
        emit(out, *b"ANAM", self.speaker.as_ref());
        emit(out, *b"TSCE", self.start_scene.as_ref());
        emit(out, *b"INTV", self.intv.as_ref());
        emit(out, *b"WED0", self.voice_override.as_ref());
        emit(out, *b"TIQS", self.set_parent_quest_stage.as_ref());
        emit(out, *b"NAM0", self.start_scene_phase.as_ref());
        emit(out, *b"MODQ", self.reset_global.as_ref());
        emit(out, *b"INAM", self.subtitle_priority.as_ref());
        emit(out, *b"COCT", self.coct.as_ref());
        emit(out, *b"NAM8", self.affinity_event.as_ref());
        emit(out, *b"SCSP", self.speech_challenge.as_ref());
        emit(out, *b"PERK", self.skill_perk.as_ref());
    }
}

