#[derive(Debug, Clone, PartialEq, Default)]
pub struct InnrRulesetsNames {
    /// `WNAM`, required.
    pub text: Option<Sub<LString>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `XNAM`, optional.
    pub property: Option<Sub<InnrRulesetsNamesProperty>>,
    /// `YNAM`, required.
    pub index: Option<Sub<u16>>,
}

impl InnrRulesetsNames {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"WNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"XNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"YNAM",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.text,
                    subs,
                    *index,
                    "INNR.Rulesets.Names.WNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 1, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.property,
                    subs,
                    *index,
                    "INNR.Rulesets.Names.XNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.index,
                    subs,
                    *index,
                    "INNR.Rulesets.Names.YNAM",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"WNAM", self.text.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"XNAM", self.property.as_ref());
        emit(out, *b"YNAM", self.index.as_ref());
    }
}

impl Visit for InnrRulesetsNames {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.keywords, "INNR.Rulesets.Names.Keywords", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.keywords, "INNR.Rulesets.Names.Keywords", out);
    }

    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.text, "INNR.Rulesets.Names.WNAM", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.text, "INNR.Rulesets.Names.WNAM", out);
    }
}

