/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct LvliFlags(pub u16);

impl LvliFlags {
    pub const CALCULATE_FROM_ALL_LEVELS: u16 = 0x1;
    pub const CALCULATE_FOR_EACH_ITEM: u16 = 0x2;
    pub const USE_ALL: u16 = 0x4;
    pub const SHOW_AS_MARKER1: u16 = 0x8;
    pub const SHOW_AS_MARKER2: u16 = 0x10;
    pub const EVAL_AS_STACK: u16 = 0x20;
    pub const GET_CHANCE_FROM_REQUIRED_BIOME: u16 = 0x80;
    pub const DO_ALL_BEFORE_REPEATING: u16 = 0x100;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u16) -> bool {
        self.0 & mask == mask
    }
}

