#[derive(Debug, Clone, PartialEq, Default)]
pub struct LvlnRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<ObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `OPDS`, optional.
    pub object_palette_defaults: Option<Sub<ObjectPaletteDefaults>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `XALG`, optional.
    pub xalg_flags2: Option<Sub<u64>>,
    /// `LVLD`, required.
    pub chance_none: Option<Sub<f32>>,
    /// `LVLM`, required.
    pub max_count: Option<Sub<u8>>,
    /// `LVLF`, required.
    pub flags: Option<Sub<LvlnFlags>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `LVLG`, optional.
    pub use_global: Option<Sub<FormId>>,
    /// `LLCT`, optional.
    pub entry_count: Option<Sub<u8>>,
    /// Group `Entry`, repeated.
    pub entry: Vec<LvlnEntry>,
    /// `LLKC`, optional.
    pub filter_keyword_chances: Option<Sub<LvlnFilterKeywordChances>>,
    /// `ONAM`, optional.
    pub override_name: Option<Sub<LString>>,
    /// Group `Model`, optional.
    pub model: Option<Model>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl LvlnRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OPDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LVLD",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"LVLM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"LVLF",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LVLG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LLCT",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: LvlnEntry::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LLKC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Model::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "LVLN.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "LVLN.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "LVLN.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "LVLN.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.object_palette_defaults,
                    subs,
                    *index,
                    "LVLN.OPDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.xalg_flags, subs, *index, "LVLN.XALG", ctx, extra)
                }
                Hit::Group { member: 6, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.xalg_flags2, subs, *index, "LVLN.XALG", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.chance_none, subs, *index, "LVLN.LVLD", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.max_count, subs, *index, "LVLN.LVLM", ctx, extra)
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.flags, subs, *index, "LVLN.LVLF", ctx, extra)
                }
                Hit::Group { member: 11, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 12, index } => {
                    put(&mut self.use_global, subs, *index, "LVLN.LVLG", ctx, extra)
                }
                Hit::Sub { member: 13, index } => {
                    put(&mut self.entry_count, subs, *index, "LVLN.LLCT", ctx, extra)
                }
                Hit::Group { member: 14, hits } => {
                    let mut group = LvlnEntry::default();
                    group.fill(hits, subs, ctx, extra);
                    self.entry.push(group);
                }
                Hit::Sub { member: 15, index } => put(
                    &mut self.filter_keyword_chances,
                    subs,
                    *index,
                    "LVLN.LLKC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => put(
                    &mut self.override_name,
                    subs,
                    *index,
                    "LVLN.ONAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 17, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"OPDS", self.object_palette_defaults.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"XALG", self.xalg_flags2.as_ref());
        emit(out, *b"LVLD", self.chance_none.as_ref());
        emit(out, *b"LVLM", self.max_count.as_ref());
        emit(out, *b"LVLF", self.flags.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"LVLG", self.use_global.as_ref());
        emit(out, *b"LLCT", self.entry_count.as_ref());
        for group in &self.entry {
            group.emit(out);
        }
        emit(out, *b"LLKC", self.filter_keyword_chances.as_ref());
        emit(out, *b"ONAM", self.override_name.as_ref());
        if let Some(group) = &self.model {
            group.emit(out);
        }
    }
}

