#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MgefSoundsType {
    DrawSheathe,
    Charge,
    Ready,
    Release,
    CastLoop,
    OnHit,
    /// A value the definition does not name.
    Other(u8),
}

impl MgefSoundsType {
    /// The variant for a stored value.
    pub fn from_raw(raw: u8) -> Self {
        match raw {
            0 => Self::DrawSheathe,
            1 => Self::Charge,
            2 => Self::Ready,
            3 => Self::Release,
            4 => Self::CastLoop,
            5 => Self::OnHit,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u8 {
        match self {
            Self::DrawSheathe => 0,
            Self::Charge => 1,
            Self::Ready => 2,
            Self::Release => 3,
            Self::CastLoop => 4,
            Self::OnHit => 5,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for MgefSoundsType {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

impl Visit for MgefSoundsType {}

