#[derive(Debug, Clone, PartialEq, Default)]
pub struct MgefRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `MDOB`, optional.
    pub menu_display_object: Option<Sub<FormId>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `DATA`, required.
    pub data: Option<Sub<MgefData>>,
    /// `ESCE`, repeated.
    pub counter_effects: Vec<Sub<FormId>>,
    /// `ESSH`, repeated.
    pub sounds: Vec<Sub<MgefSounds>>,
    /// `DNAM`, optional.
    pub magic_item_description: Option<Sub<LString>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl MgefRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"MDOB",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ESCE",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"ESSH",
            card: Card::Repeated,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "MGEF.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "MGEF.VMAD", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.name, subs, *index, "MGEF.FULL", ctx, extra)
                }
                Hit::Sub { member: 4, index } => put(
                    &mut self.menu_display_object,
                    subs,
                    *index,
                    "MGEF.MDOB",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 5, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.data, subs, *index, "MGEF.DATA", ctx, extra)
                }
                Hit::Sub { member: 7, index } => push(
                    &mut self.counter_effects,
                    subs,
                    *index,
                    "MGEF.ESCE",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => {
                    push(&mut self.sounds, subs, *index, "MGEF.ESSH", ctx, extra)
                }
                Hit::Sub { member: 9, index } => put(
                    &mut self.magic_item_description,
                    subs,
                    *index,
                    "MGEF.DNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 10, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"MDOB", self.menu_display_object.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"DATA", self.data.as_ref());
        for value in &self.counter_effects {
            emit(out, *b"ESCE", Some(value));
        }
        for value in &self.sounds {
            emit(out, *b"ESSH", Some(value));
        }
        emit(out, *b"DNAM", self.magic_item_description.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
    }
}

impl Visit for MgefRecord {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.bfcb_block, "MGEF.BfcbBlock", out);
        visit_form_ids(&self.menu_display_object, "MGEF.MDOB", out);
        visit_form_ids(&self.keywords, "MGEF.Keywords", out);
        visit_form_ids(&self.data, "MGEF.DATA", out);
        visit_form_ids(&self.counter_effects, "MGEF.ESCE", out);
        visit_form_ids(&self.sounds, "MGEF.ESSH", out);
        visit_form_ids(&self.conditions, "MGEF.Conditions", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.bfcb_block, "MGEF.BfcbBlock", out);
        visit_form_ids_mut(&mut self.menu_display_object, "MGEF.MDOB", out);
        visit_form_ids_mut(&mut self.keywords, "MGEF.Keywords", out);
        visit_form_ids_mut(&mut self.data, "MGEF.DATA", out);
        visit_form_ids_mut(&mut self.counter_effects, "MGEF.ESCE", out);
        visit_form_ids_mut(&mut self.sounds, "MGEF.ESSH", out);
        visit_form_ids_mut(&mut self.conditions, "MGEF.Conditions", out);
    }

    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.name, "MGEF.FULL", out);
        visit_lstrings(&self.magic_item_description, "MGEF.DNAM", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.name, "MGEF.FULL", out);
        visit_lstrings_mut(&mut self.magic_item_description, "MGEF.DNAM", out);
    }
}

impl MgefRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"MGEF";

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at the
    /// indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("MGEF", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("MGEF", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("MGEF", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("MGEF", &mut out);
        out
    }
}

