#[derive(Debug, Clone, PartialEq, Default)]
pub struct NpcPerks {
    /// `PRKZ`, required.
    pub count: Option<Sub<u32>>,
    /// `PRKR`, repeated.
    pub perk: Vec<Sub<NpcPerksPerk>>,
}

impl NpcPerks {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"PRKZ",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"PRKR",
            card: Card::Repeated,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.count, subs, *index, "NPC_.Perks.PRKZ", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    push(&mut self.perk, subs, *index, "NPC_.Perks.PRKR", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"PRKZ", self.count.as_ref());
        for value in &self.perk {
            emit(out, *b"PRKR", Some(value));
        }
    }
}

impl Visit for NpcPerks {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.perk, "NPC_.Perks.PRKR", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.perk, "NPC_.Perks.PRKR", out);
    }
}

