impl NpcMorphBlend {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"BMPN",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BMPV",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.name,
                    subs,
                    *index,
                    "NPC_.MorphBlend.BMPN",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.intensity,
                    subs,
                    *index,
                    "NPC_.MorphBlend.BMPV",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"BMPN", self.name.as_ref());
        emit(out, *b"BMPV", self.intensity.as_ref());
    }
}

impl Visit for NpcMorphBlend {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NpcPronoun {
    Unspecified,
    HeHim,
    SheHer,
    TheyThem,
    /// A value the definition does not name.
    Other(u8),
}

impl NpcPronoun {
    /// The variant for a stored value.
    pub fn from_raw(raw: u8) -> Self {
        match raw {
            0 => Self::Unspecified,
            1 => Self::HeHim,
            2 => Self::SheHer,
            3 => Self::TheyThem,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u8 {
        match self {
            Self::Unspecified => 0,
            Self::HeHim => 1,
            Self::SheHer => 2,
            Self::TheyThem => 3,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for NpcPronoun {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

impl Visit for NpcPronoun {}

/// Bit flags; bits without a name are preserved.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct NpcRaceOverridesFlags(pub u32);

impl NpcRaceOverridesFlags {
    pub const SIZE: u32 = 0x1;
    pub const MOVEMENT: u32 = 0x2;
    pub const FLIGHT: u32 = 0x4;
    pub const UNARMED_WEAPON: u32 = 0x8;
    pub const FLAG_OVERRIDES: u32 = 0x10;
    pub const BLEEDOUT: u32 = 0x20;
    pub const GENERAL: u32 = 0x40;
    pub const ELECTROMAGNETIC: u32 = 0x80;

    /// Whether every bit of `mask` is set.
    pub fn contains(self, mask: u32) -> bool {
        self.0 & mask == mask
    }
}

impl Field for NpcRaceOverridesFlags {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u32::read(r, field, ctx).map(Self)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.0.write(out);
    }
}

impl Visit for NpcRaceOverridesFlags {}

#[derive(Debug, Clone, PartialEq)]
pub struct NpcRaceOverrides {
    pub flags: NpcRaceOverridesFlags,
    pub overrides: Bytes,
}

impl Field for NpcRaceOverrides {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = Field::read(r, "NPC_.ONA2.Flags", ctx)?;
        let f1 = Field::read(r, "NPC_.ONA2.Overrides", ctx)?;
        Ok(Self {
            flags: f0,
            overrides: f1,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.flags.write(out);
        self.overrides.write(out);
    }
}

impl Visit for NpcRaceOverrides {}

