#[derive(Debug, Clone, PartialEq, Default)]
pub struct PackRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<ScriptAttachment>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `PKDT`, required.
    pub pack_data: Option<Sub<PackPackData>>,
    /// `PSDT`, required.
    pub schedule: Option<Sub<PackSchedule>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// Group `IdleAnimations`, optional.
    pub idle_animations: Option<PackIdleAnimations>,
    /// `CNAM`, optional.
    pub combat_style: Option<Sub<FormId>>,
    /// `QNAM`, optional.
    pub owner_quest: Option<Sub<FormId>>,
    /// `FLAV`, optional.
    pub anim_flavor: Option<Sub<FormId>>,
    /// `PKCU`, required.
    pub counter: Option<Sub<PackCounter>>,
    /// Group `PackageData`, optional.
    pub package_data: Option<PackPackageData>,
    /// `XNAM`, required.
    pub package_group: Option<Sub<u8>>,
    /// Group `Branch`, repeated.
    pub branch: Vec<PackBranch>,
    /// Group `NamedDataInputs`, repeated.
    pub named_data_inputs: Vec<PackNamedDataInputs>,
    /// Group `OnBegin`, optional.
    pub on_begin: Option<PackOnBegin>,
    /// Group `OnEnd`, optional.
    pub on_end: Option<PackOnEnd>,
    /// Group `OnChange`, optional.
    pub on_change: Option<PackOnChange>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl PackRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"PKDT",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"PSDT",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PackIdleAnimations::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"CNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"QNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FLAV",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PKCU",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PackPackageData::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"XNAM",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: PackBranch::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: PackNamedDataInputs::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PackOnBegin::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PackOnEnd::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PackOnChange::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "PACK.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "PACK.VMAD", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.pack_data, subs, *index, "PACK.PKDT", ctx, extra)
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.schedule, subs, *index, "PACK.PSDT", ctx, extra)
                }
                Hit::Group { member: 5, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Group { member: 6, hits } if self.idle_animations.is_none() => {
                    let mut group = PackIdleAnimations::default();
                    group.fill(hits, subs, ctx, extra);
                    self.idle_animations = Some(group);
                }
                Hit::Sub { member: 7, index } => put(
                    &mut self.combat_style,
                    subs,
                    *index,
                    "PACK.CNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => {
                    put(&mut self.owner_quest, subs, *index, "PACK.QNAM", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.anim_flavor, subs, *index, "PACK.FLAV", ctx, extra)
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.counter, subs, *index, "PACK.PKCU", ctx, extra)
                }
                Hit::Group { member: 11, hits } if self.package_data.is_none() => {
                    let mut group = PackPackageData::default();
                    group.fill(hits, subs, ctx, extra);
                    self.package_data = Some(group);
                }
                Hit::Sub { member: 12, index } => put(
                    &mut self.package_group,
                    subs,
                    *index,
                    "PACK.XNAM",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 13, hits } => {
                    let mut group = PackBranch::default();
                    group.fill(hits, subs, ctx, extra);
                    self.branch.push(group);
                }
                Hit::Group { member: 14, hits } => {
                    let mut group = PackNamedDataInputs::default();
                    group.fill(hits, subs, ctx, extra);
                    self.named_data_inputs.push(group);
                }
                Hit::Group { member: 15, hits } if self.on_begin.is_none() => {
                    let mut group = PackOnBegin::default();
                    group.fill(hits, subs, ctx, extra);
                    self.on_begin = Some(group);
                }
                Hit::Group { member: 16, hits } if self.on_end.is_none() => {
                    let mut group = PackOnEnd::default();
                    group.fill(hits, subs, ctx, extra);
                    self.on_end = Some(group);
                }
                Hit::Group { member: 17, hits } if self.on_change.is_none() => {
                    let mut group = PackOnChange::default();
                    group.fill(hits, subs, ctx, extra);
                    self.on_change = Some(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"PKDT", self.pack_data.as_ref());
        emit(out, *b"PSDT", self.schedule.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        if let Some(group) = &self.idle_animations {
            group.emit(out);
        }
        emit(out, *b"CNAM", self.combat_style.as_ref());
        emit(out, *b"QNAM", self.owner_quest.as_ref());
        emit(out, *b"FLAV", self.anim_flavor.as_ref());
        emit(out, *b"PKCU", self.counter.as_ref());
        if let Some(group) = &self.package_data {
            group.emit(out);
        }
        emit(out, *b"XNAM", self.package_group.as_ref());
        for group in &self.branch {
            group.emit(out);
        }
        for group in &self.named_data_inputs {
            group.emit(out);
        }
        if let Some(group) = &self.on_begin {
            group.emit(out);
        }
        if let Some(group) = &self.on_end {
            group.emit(out);
        }
        if let Some(group) = &self.on_change {
            group.emit(out);
        }
    }
}

