#[derive(Debug, Clone, PartialEq, Default)]
pub struct PerkRank {
    /// `PRRK`, required.
    pub start: Option<Sub<Empty>>,
    /// Group `Effect`, repeated.
    pub effect: Vec<PerkRankEffect>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// Group `ActivityTracker`, optional.
    pub activity_tracker: Option<PerkRankActivityTracker>,
    /// `DESC`, required.
    pub description: Option<Sub<LString>>,
    /// `PRUC`, optional.
    pub upgrade_cost: Option<Sub<u32>>,
    /// `PRRF`, required.
    pub end: Option<Sub<Empty>>,
}

impl PerkRank {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"PRRK",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: PerkRankEffect::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: PerkRankActivityTracker::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DESC",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"PRUC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PRRF",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.start, subs, *index, "PERK.Rank.PRRK", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = PerkRankEffect::default();
                    group.fill(hits, subs, ctx, extra);
                    self.effect.push(group);
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Group { member: 3, hits } if self.activity_tracker.is_none() => {
                    let mut group = PerkRankActivityTracker::default();
                    group.fill(hits, subs, ctx, extra);
                    self.activity_tracker = Some(group);
                }
                Hit::Sub { member: 4, index } => put(
                    &mut self.description,
                    subs,
                    *index,
                    "PERK.Rank.DESC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => put(
                    &mut self.upgrade_cost,
                    subs,
                    *index,
                    "PERK.Rank.PRUC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 6, index } => {
                    put(&mut self.end, subs, *index, "PERK.Rank.PRRF", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"PRRK", self.start.as_ref());
        for group in &self.effect {
            group.emit(out);
        }
        for group in &self.conditions {
            group.emit(out);
        }
        if let Some(group) = &self.activity_tracker {
            group.emit(out);
        }
        emit(out, *b"DESC", self.description.as_ref());
        emit(out, *b"PRUC", self.upgrade_cost.as_ref());
        emit(out, *b"PRRF", self.end.as_ref());
    }
}

