#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RaceSubgraphFlagsRole {
    Mt,
    Weapon,
    Furniture,
    LinkingOnly,
    Pipboy,
    MtGeneration,
    WeaponGeneration,
    FurnitureGeneration,
    /// A value the definition does not name.
    Other(u16),
}

impl RaceSubgraphFlagsRole {
    /// The variant for a stored value.
    pub fn from_raw(raw: u16) -> Self {
        match raw {
            0 => Self::Mt,
            1 => Self::Weapon,
            2 => Self::Furniture,
            3 => Self::LinkingOnly,
            4 => Self::Pipboy,
            5 => Self::MtGeneration,
            6 => Self::WeaponGeneration,
            7 => Self::FurnitureGeneration,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u16 {
        match self {
            Self::Mt => 0,
            Self::Weapon => 1,
            Self::Furniture => 2,
            Self::LinkingOnly => 3,
            Self::Pipboy => 4,
            Self::MtGeneration => 5,
            Self::WeaponGeneration => 6,
            Self::FurnitureGeneration => 7,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for RaceSubgraphFlagsRole {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u16::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

