#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScenSpeechChallengeRisk {
    Easy,
    Medium,
    Hard,
    Always,
    /// A value the definition does not name.
    Other(u16),
}

impl ScenSpeechChallengeRisk {
    /// The variant for a stored value.
    pub fn from_raw(raw: u16) -> Self {
        match raw {
            0 => Self::Easy,
            1 => Self::Medium,
            2 => Self::Hard,
            3 => Self::Always,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u16 {
        match self {
            Self::Easy => 0,
            Self::Medium => 1,
            Self::Hard => 2,
            Self::Always => 3,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for ScenSpeechChallengeRisk {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u16::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

