#[derive(Debug, Clone, PartialEq)]
pub struct StatDirectionMaterial {
    pub max_angle: f32,
    pub value2: f32,
    /// Present only when bytes remain in the payload.
    pub leaf: Option<StatDirectionMaterialLeaf>,
}

impl Field for StatDirectionMaterial {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = f32::read(r, "STAT.DNAM.MaxAngle", ctx)?;
        let f1 = f32::read(r, "STAT.DNAM.Value2", ctx)?;
        let f2 = if !r.is_empty() {
            Some(Field::read(r, "STAT.DNAM.Leaf", ctx)?)
        } else {
            None
        };
        Ok(Self {
            max_angle: f0,
            value2: f1,
            leaf: f2,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.max_angle.write(out);
        self.value2.write(out);
        if let Some(value) = &self.leaf {
            value.write(out);
        }
    }
}

