#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TermArtTheme {
    Constellation,
    FreestarCollective,
    Generic,
    Nasa,
    RyujinIndustries,
    SlaytonAerospace,
    UnitedColonies,
    CrimsonFleet,
    HouseVaruun,
    ShipUpgrade,
    TerranArmada,
    /// A value the definition does not name.
    Other(u8),
}

impl TermArtTheme {
    /// The variant for a stored value.
    pub fn from_raw(raw: u8) -> Self {
        match raw {
            0 => Self::Constellation,
            1 => Self::FreestarCollective,
            2 => Self::Generic,
            3 => Self::Nasa,
            4 => Self::RyujinIndustries,
            5 => Self::SlaytonAerospace,
            6 => Self::UnitedColonies,
            7 => Self::CrimsonFleet,
            9 => Self::HouseVaruun,
            10 => Self::ShipUpgrade,
            11 => Self::TerranArmada,
            other => Self::Other(other),
        }
    }

    /// The stored value.
    pub fn to_raw(self) -> u8 {
        match self {
            Self::Constellation => 0,
            Self::FreestarCollective => 1,
            Self::Generic => 2,
            Self::Nasa => 3,
            Self::RyujinIndustries => 4,
            Self::SlaytonAerospace => 5,
            Self::UnitedColonies => 6,
            Self::CrimsonFleet => 7,
            Self::HouseVaruun => 9,
            Self::ShipUpgrade => 10,
            Self::TerranArmada => 11,
            Self::Other(raw) => raw,
        }
    }
}

impl Field for TermArtTheme {
    fn read(r: &mut Reader<'_>, field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        u8::read(r, field, ctx).map(Self::from_raw)
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.to_raw().write(out);
    }
}

