pub struct TmlmRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `TMVT`, required.
    pub show_body_text: Option<Sub<TmlmShowBodyText>>,
    /// `DNAM`, required.
    pub menu_button_style: Option<Sub<TmlmMenuButtonStyle>>,
    /// `SNAM`, required.
    pub style: Option<Sub<TmlmStyle>>,
    /// `INAM`, required.
    pub inam: Option<Sub<LString>>,
    /// `BSIZ`, required.
    pub body_text_count: Option<Sub<u32>>,
    /// Group `BodyText`, repeated.
    pub body_text: Vec<TmlmBodyText>,
    /// `ISIZ`, required.
    pub menu_item_count: Option<Sub<u32>>,
    /// Group `MenuItem`, repeated.
    pub menu_item: Vec<TmlmMenuItem>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl TmlmRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"TMVT",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"SNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"INAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"BSIZ",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: TmlmBodyText::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"ISIZ",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: TmlmMenuItem::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "TMLM.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "TMLM.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.name, subs, *index, "TMLM.FULL", ctx, extra)
                }
                Hit::Sub { member: 3, index } => put(
                    &mut self.show_body_text,
                    subs,
                    *index,
                    "TMLM.TMVT",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.menu_button_style,
                    subs,
                    *index,
                    "TMLM.DNAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.style, subs, *index, "TMLM.SNAM", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.inam, subs, *index, "TMLM.INAM", ctx, extra)
                }
                Hit::Sub { member: 7, index } => put(
                    &mut self.body_text_count,
                    subs,
                    *index,
                    "TMLM.BSIZ",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 8, hits } => {
                    let mut group = TmlmBodyText::default();
                    group.fill(hits, subs, ctx, extra);
                    self.body_text.push(group);
                }
                Hit::Sub { member: 9, index } => put(
                    &mut self.menu_item_count,
                    subs,
                    *index,
                    "TMLM.ISIZ",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 10, hits } => {
                    let mut group = TmlmMenuItem::default();
                    group.fill(hits, subs, ctx, extra);
                    self.menu_item.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"TMVT", self.show_body_text.as_ref());
        emit(out, *b"DNAM", self.menu_button_style.as_ref());
        emit(out, *b"SNAM", self.style.as_ref());
        emit(out, *b"INAM", self.inam.as_ref());
        emit(out, *b"BSIZ", self.body_text_count.as_ref());
        for group in &self.body_text {
            group.emit(out);
        }
        emit(out, *b"ISIZ", self.menu_item_count.as_ref());
        for group in &self.menu_item {
            group.emit(out);
        }
    }
}

