#[derive(Debug, Clone, PartialEq, Default)]
pub struct WeapEnchantment {
    /// `EITM`, optional.
    pub effect: Option<Sub<FormId>>,
    /// `EAMT`, optional.
    pub capacity: Option<Sub<u16>>,
}

impl WeapEnchantment {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EITM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"EAMT",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.effect,
                    subs,
                    *index,
                    "WEAP.Enchantment.EITM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.capacity,
                    subs,
                    *index,
                    "WEAP.Enchantment.EAMT",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EITM", self.effect.as_ref());
        emit(out, *b"EAMT", self.capacity.as_ref());
    }
}

impl Visit for WeapEnchantment {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.effect, "WEAP.Enchantment.EITM", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.effect, "WEAP.Enchantment.EITM", out);
    }
}

