#[derive(Debug, Clone, PartialEq, Default)]
pub struct WeapFirstPersonModel {
    /// `MOD4`, optional.
    pub file_name: Option<Sub<ZString>>,
    /// `MO4C`, optional.
    pub mo4c: Option<Sub<Bytes>>,
    /// `FLLD`, required.
    pub light_layer: Option<Sub<WeapFirstPersonModelLightLayer>>,
    /// `MO4S`, optional.
    pub color_remapping_index: Option<Sub<f32>>,
}

impl WeapFirstPersonModel {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"MOD4",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"MO4C",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FLLD",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"MO4S",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.file_name,
                    subs,
                    *index,
                    "WEAP.FirstPersonModel.MOD4",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.mo4c,
                    subs,
                    *index,
                    "WEAP.FirstPersonModel.MO4C",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 2, index } => put(
                    &mut self.light_layer,
                    subs,
                    *index,
                    "WEAP.FirstPersonModel.FLLD",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.color_remapping_index,
                    subs,
                    *index,
                    "WEAP.FirstPersonModel.MO4S",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"MOD4", self.file_name.as_ref());
        emit(out, *b"MO4C", self.mo4c.as_ref());
        emit(out, *b"FLLD", self.light_layer.as_ref());
        emit(out, *b"MO4S", self.color_remapping_index.as_ref());
    }
}

impl Visit for WeapFirstPersonModel {}

